INSERT INTO `duas` (`id`, `type`, `category_id`, `priority`, `tags`, `arabic_text`, `reciter`, `audio_duration`, `audio_url`, `quran_surah`, `quran_ayah`, `quran_juz`, `hadith_book`, `hadith_chapter`, `hadith_number`, `source`, `authenticity`, `when_to_recite`, `frequency`, `difficulty`, `estimated_time`, `related_duas`, `notes`, `status`, `reviewed_by`, `reviewed_at`, `view_count`, `favorite_count`, `last_read`, `created_at`, `updated_at`) VALUES ('c1','hadith',6,3,'[]','بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.906','2026-10-25 18:31:37.906'),
('dua_010','hadith',5,1,'[\"ramadan\",\"fasting\",\"blessing\"]','ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ','Abdul Rahman Al-Sudais','00:00:20','https://api.example.com/audio/dua_010.mp3',NULL,NULL,NULL,'Abu Dawud','Fasting','2357','','','[\"When breaking fast\",\"During Ramadan\"]','special','beginner','00:00:25','[]','Essential dua for breaking fast in Ramadan','published','',NULL,0,0,NULL,'2026-10-25 18:31:47.958','2026-10-26 00:38:49.933'),
('dua_012','hadith',9,1,'[\"family\",\"children\",\"blessing\"]','رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ','Abdul Rahman Al-Sudais','00:00:25','https://api.example.com/audio/dua_012.mp3',NULL,NULL,NULL,'Quran','Al-Imran','3:38','','','[\"For children\",\"Family planning\",\"Seeking offspring\"]','occasional','beginner','00:00:30','[]','Beautiful dua for seeking blessed children','published','',NULL,0,0,NULL,'2026-10-25 18:31:47.962','2026-10-25 18:31:47.962'),
('dua-evening-1','hadith',3,3,'[]','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.890','2026-10-25 18:31:37.890'),
('dua-family-1','quranic',9,3,'[]','رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا','','','',25,74,NULL,'','','','Quran 25:74','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.897','2026-10-25 18:31:37.897'),
('dua-food-1','hadith',6,3,'[]','بِسْمِ اللَّهِ','','','',NULL,NULL,NULL,'Bukhari','','','Bukhari','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.893','2026-10-25 18:31:37.893'),
('dua-gratitude-1','hadith',11,3,'[]','اللَّهُمَّ لَكَ الْحَمْدُ حَتَّى تَرْضَى، وَلَكَ الْحَمْدُ إِذَا رَضِيتَ، وَلَكَ الْحَمْدُ بَعْدَ الرِّضَا','','','',NULL,NULL,NULL,'Ibn Majah','','','Ibn Majah','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.902','2026-10-25 18:31:37.902'),
('dua-hajj-umrah-1','hadith',13,3,'[]','اللَّهُمَّ إِنِّي أُرِيدُ الْحَجَّ فَيَسِّرْهُ لِي وَتَقَبَّلْهُ مِنِّي','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.904','2026-10-25 18:31:37.904'),
('dua-illness-1','hadith',7,3,'[]','أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.898','2026-10-25 18:31:37.898'),
('dua-morning-1','hadith',2,3,'[]','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.887','2026-10-25 18:31:37.887'),
('dua-nature-1','hadith',15,3,'[]','اللَّهُمَّ صَيِّبًا نَافِعًا','','','',NULL,NULL,NULL,'Bukhari','','','Bukhari','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.905','2026-10-25 18:31:37.905'),
('dua-purification-1','hadith',12,3,'[]','اللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُطَهَّرُ الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.903','2026-10-25 18:31:37.903'),
('dua-ramadan-1','hadith',5,3,'[]','اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.891','2026-10-25 18:31:37.891'),
('dua-rizq-1','hadith',10,3,'[]','اللَّهُمَّ إِنِّي أَسْأَلُكَ رِزْقًا طَيِّبًا وَرِزْقًا وَاسِعًا','','','',NULL,NULL,NULL,'Ibn Majah','','','Ibn Majah','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.900','2026-10-25 18:31:37.900'),
('dua-ruqyah-1','hadith',8,3,'[]','أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.899','2026-10-25 18:31:37.899'),
('dua-salah-1','hadith',1,3,'[]','اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ','','','',NULL,NULL,NULL,'Bukhari','','','Bukhari','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.895','2026-10-25 18:31:37.895'),
('dua-sleep-1','hadith',4,3,'[]','بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ','','','',NULL,NULL,NULL,'Bukhari','','','Bukhari','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.896','2026-10-25 18:31:37.896'),
('dua-travel-1','hadith',14,3,'[]','اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.894','2026-10-25 18:31:37.894'),
('h1','hadith',2,3,'[]','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.872','2026-10-25 18:31:37.872'),
('h2','hadith',3,3,'[]','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.875','2026-10-25 18:31:37.875'),
('h3','hadith',6,3,'[]','بِسْمِ اللَّهِ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.879','2026-10-25 18:31:37.879'),
('h4','hadith',6,3,'[]','الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.882','2026-10-25 18:31:37.882'),
('h5','hadith',14,3,'[]','اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى','','','',NULL,NULL,NULL,'Muslim','','','Muslim','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.883','2026-10-25 18:31:37.883'),
('h6','hadith',16,3,'[]','بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.884','2026-10-25 18:31:37.884'),
('h7','hadith',16,3,'[]','بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.885','2026-10-25 18:31:37.885'),
('h8','hadith',16,3,'[]','الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ','','','',NULL,NULL,NULL,'Abu Dawud','','','Abu Dawud','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.886','2026-10-25 18:31:37.886'),
('q1','quranic',8,3,'[]','اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ','','','',2,255,NULL,'','','','Quran 2:255','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.861','2026-10-26 00:38:49.933'),
('q2','quranic',1,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾','','','',1,1,NULL,'','','','Quran 1:1-7','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.863','2026-10-25 18:31:37.863'),
('q3','quranic',8,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ قُلْ هُوَ اللَّهُ أَحَدٌ ﴿٢﴾ اللَّهُ الصَّمَدُ ﴿٣﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٤﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿٥﴾','','','',112,1,NULL,'','','','Quran 112:1-4','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.865','2026-10-25 18:31:37.865'),
('q4','quranic',8,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿٢﴾ مِن شَرِّ مَا خَلَقَ ﴿٣﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٤﴾ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٥﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٦﴾','','','',113,1,NULL,'','','','Quran 113:1-5','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.866','2026-10-25 18:31:37.866'),
('q5','quranic',8,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿٢﴾ مَلِكِ النَّاسِ ﴿٣﴾ إِلَٰهِ النَّاسِ ﴿٤﴾ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٥﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٦﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٧﴾','','','',114,1,NULL,'','','','Quran 114:1-6','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.867','2026-10-25 18:31:37.867'),
('q6','quranic',4,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ ﴿٢﴾ الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ ﴿٣﴾','','','',67,1,NULL,'','','','Quran 67:1-30','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.868','2026-10-25 18:31:37.868'),
('q7','quranic',NULL,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ يس ﴿٢﴾ وَالْقُرْآنِ الْحَكِيمِ ﴿٣﴾ إِنَّكَ لَمِنَ الْمُرْسَلِينَ ﴿٤﴾ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ ﴿٥﴾','','','',36,1,NULL,'','','','Quran 36:1-83','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.869','2026-10-25 18:31:37.869'),
('q8','quranic',NULL,3,'[]','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ إِذَا وَقَعَتِ الْوَاقِعَةُ ﴿٢﴾ لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ ﴿٣﴾ خَافِضَةٌ رَّافِعَةٌ ﴿٤﴾ إِذَا رُجَّتِ الْأَرْضُ رَجًّا ﴿٥﴾','','','',56,1,NULL,'','','','Quran 56:1-96','','[]','daily','beginner','00:00:30','[]','','published','',NULL,0,0,NULL,'2026-10-25 18:31:37.870','2026-10-25 18:31:37.870');
INSERT INTO `dua_translations` (`dua_id`, `lang`, `title`, `transliteration`, `translation`, `explanation`, `benefits`) VALUES ('c1','en','Dua Before Eating','Bismillahi wa \'ala millati rasoolillah','In the name of Allah and upon the religion of the Messenger of Allah','','This dua brings blessings to the food and protects from harm. It is recommended to recite before starting any meal.'),
('dua_010','ar','دعاء الإفطار','ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ','ذهب الظمأ، وابتلت العروق، وثبت الأجر إن شاء الله','يُقرأ هذا الدعاء عند الإفطار في رمضان','بركات الصيام، الشكر، الأجر الروحي'),
('dua_010','bn','রোজা ভাঙার দুআ','ধাহাবাধ ধামাউ ওয়াবতাল্লাতিল উরুকু, ওয়া সাবাতাল আজরু ইনশা আল্লাহ','পিপাসা চলে গেছে, শিরাগুলি সিক্ত হয়েছে, এবং পুরস্কার নিশ্চিত হয়েছে, আল্লাহ চাইলে','এই দুআটি রমজানে রোজা ভাঙার সময় পাঠ করা হয়','রোজার বরকত, কৃতজ্ঞতা, আধ্যাত্মিক পুরস্কার'),
('dua_010','de','Dua zum Fastenbrechen','Dhahabadh dhama\'u wabtallatil \'urooqu, wa thabatal ajru inshaa Allaah','Der Durst ist vergangen, die Adern sind befeuchtet, und die Belohnung ist bestätigt, wenn Allah es will','Dieses Dua wird beim Fastenbrechen im Ramadan rezitiert','Segen des Fastens, Dankbarkeit, spirituelle Belohnung'),
('dua_010','en','Dua for Breaking Fast','Dhahabadh dhama\'u wabtallatil \'urooqu, wa thabatal ajru inshaa Allaah','The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills','This dua is recited when breaking the fast during Ramadan','Blessings of fasting, gratitude, spiritual reward'),
('dua_010','es','Dua para romper el ayuno','Dhahabadh dhama\'u wabtallatil \'urooqu, wa thabatal ajru inshaa Allaah','La sed se ha ido, las venas están humedecidas, y la recompensa está confirmada, si Alá quiere','Este dua se recita al romper el ayuno durante el Ramadán','Bendiciones del ayuno, gratitud, recompensa espiritual'),
('dua_010','id','Doa untuk berbuka puasa','Dhahabadh dhama\'u wabtallatil \'urooqu, wa thabatal ajru inshaa Allaah','Haus telah hilang, pembuluh darah telah dibasahi, dan pahala telah dikonfirmasi, jika Allah menghendaki','Doa ini dibaca saat berbuka puasa selama Ramadhan','Berkah puasa, syukur, pahala spiritual'),
('dua_010','ur','روزہ افطار کی دعا','ذہب الظما وابتلت العروق وثبت الاجر ان شاء اللہ','پیاس چلی گئی، رگیں تر ہو گئیں، اور اجر ثابت ہو گیا، اللہ چاہے تو','یہ دعا رمضان میں روزہ افطار کرتے وقت پڑھی جاتی ہے','روزے کی برکتیں، شکرگزاری، روحانی اجر'),
('dua_012','ar','دعاء للأطفال','رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ','ربي هب لي من لدنك ذرية طيبة إنك سميع الدعاء','يُقرأ هذا الدعاء لطلب أطفال مباركين وصالحين','الأطفال المباركون، الانسجام الأسري، النعمة الإلهية'),
('dua_012','bn','সন্তানের দুআ','রাব্বি হাব লি মিন লাদুনকা ধুররিয়্যাতান তাইয়্যিবাহ, ইন্নাকা সামীউদ দুআ','হে আমার প্রভু, আমাকে আপনার কাছ থেকে উত্তম সন্তান দিন। নিশ্চয় আপনি প্রার্থনা শ্রবণকারী','এই দুআটি আশীর্বাদপূর্ণ এবং ধার্মিক সন্তান কামনা করার জন্য পাঠ করা হয়','আশীর্বাদপূর্ণ সন্তান, পারিবারিক সাদৃশ্য, ঐশ্বরিক অনুগ্রহ'),
('dua_012','de','Dua für Kinder','Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka samee\'ud-du\'aa','Mein Herr, gewähre mir von Dir eine gute Nachkommenschaft. Du bist der Hörende der Bitte','Dieses Dua wird rezitiert, um gesegnete und rechtschaffene Kinder zu erbitten','Gesegnete Kinder, familiäre Harmonie, göttliche Gunst'),
('dua_012','en','Dua for Children','Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka samee\'ud-du\'aa','My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication','This dua is recited to seek blessed and righteous children','Blessed children, family harmony, divine favor'),
('dua_012','es','Dua para niños','Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka samee\'ud-du\'aa','Mi Señor, concédeme de Ti una buena descendencia. En verdad, Tú eres el Oyente de la súplica','Este dua se recita para pedir hijos bendecidos y rectos','Hijos bendecidos, armonía familiar, favor divino'),
('dua_012','id','Doa untuk anak-anak','Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka samee\'ud-du\'aa','Ya Tuhanku, berikanlah kepadaku keturunan yang baik dari sisi-Mu. Sesungguhnya Engkau Maha Mendengar doa','Doa ini dibaca untuk memohon anak-anak yang diberkati dan saleh','Anak-anak yang diberkati, keharmonisan keluarga, karunia ilahi'),
('dua_012','ur','بچوں کی دعا','رب ہب لی من لدنک ذریۃ طیبۃ انک سمیع الدعا','اے میرے رب! مجھے اپنی طرف سے اچھی اولاد عطا فرما۔ بے شک آپ دعا سننے والے ہیں','یہ دعا مبارک اور نیک بچوں کے لیے پڑھی جاتی ہے','مبارک بچے، خاندانی ہم آہنگی، الہی فضل'),
('dua-evening-1','ar','دعاء المساء','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','يُقرأ هذا الدعاء في المساء لطلب حماية الله وبركاته للليل','الحماية للليل، البركات، القوة الروحية'),
('dua-evening-1','bn','সন্ধ্যার দুআ','আমসায়না ওয়া আমসাল মুলকু লিল্লাহ, ওয়ালহামদু লিল্লাহ, লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহ','আমরা সন্ধ্যায় পৌঁছেছি এবং এই মুহূর্তে সব সার্বভৌমত্ব আল্লাহর। সব প্রশংসা আল্লাহর জন্য। আল্লাহ ছাড়া কেউ উপাসনার যোগ্য নয়, তিনি একক, কোনো অংশীদার ছাড়া','এই দুআটি সন্ধ্যায় আল্লাহর সুরক্ষা এবং রাতের জন্য বরকত কামনা করার জন্য পাঠ করা হয়','রাতের জন্য সুরক্ষা, বরকত, আধ্যাত্মিক শক্তি'),
('dua-evening-1','de','Abend-Dua','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Wir haben den Abend erreicht und zu dieser Zeit gehört alle Souveränität Allah. Aller Preis gebührt Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne Partner','Dieses Dua wird abends rezitiert, um Allahs Schutz und Segen für die Nacht zu erbitten','Schutz für die Nacht, Segen, spirituelle Stärke'),
('dua-evening-1','en','Dua for Evening','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','We have reached the evening and at this very time all sovereignty belongs to Allah. All praise is for Allah. None has the right to be worshipped except Allah, alone, without any partner.','','This dua is recited in the evening to thank Allah for the day and seek His protection for the night.'),
('dua-evening-1','es','Dua de la tarde','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Hemos llegado a la tarde y en este momento toda soberanía pertenece a Alá. Toda alabanza es para Alá. Nadie tiene derecho a ser adorado excepto Alá, solo, sin ningún socio','Este dua se recita por la tarde para buscar la protección y bendiciones de Alá para la noche','Protección para la noche, bendiciones, fuerza espiritual'),
('dua-evening-1','id','Doa sore','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Kami telah mencapai sore dan pada saat ini semua kedaulatan milik Allah. Semua pujian untuk Allah. Tidak ada yang berhak disembah kecuali Allah, sendirian, tanpa partner','Doa ini dibaca di sore hari untuk memohon perlindungan dan berkah Allah untuk malam ini','Perlindungan untuk malam ini, berkah, kekuatan spiritual'),
('dua-evening-1','ur','شام کی دعا','امسینا وامسا الملک للہ، والحمد للہ، لا الہ الا اللہ وحدہ لا شریک لہ','ہم شام کو پہنچ گئے اور اس وقت تمام بادشاہی اللہ کی ہے۔ تمام تعریفیں اللہ کے لیے ہیں۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، کوئی شریک نہیں','یہ دعا شام کو اللہ کی حفاظت اور رات کی برکت کے لیے پڑھی جاتی ہے','رات کی حفاظت، برکتیں، روحانی طاقت'),
('dua-family-1','en','Dua for Family','Rabbana hab lana min azwajina wa dhurriyyatina qurrata a\'yunin waj\'alna lil-muttaqina imama','Our Lord, grant us from among our spouses and offspring comfort to our eyes and make us an example for the righteous','','This dua is recited to ask Allah for righteous spouses and children who will be a source of joy and comfort.'),
('dua-food-1','ar','الدعاء قبل الأكل','بِسْمِ اللَّهِ','باسم الله','يُقرأ هذا الدعاء قبل الأكل لطلب بركة الله على الطعام','البركة على الطعام، الحماية من الأذى، الشكر'),
('dua-food-1','bn','খাওয়ার আগের দুআ','বিসমিল্লাহ','আল্লাহর নামে','এই দুআটি খাওয়ার আগে খাবারে আল্লাহর বরকত কামনা করার জন্য পাঠ করা হয়','খাবারে বরকত, ক্ষতি থেকে সুরক্ষা, কৃতজ্ঞতা'),
('dua-food-1','de','Dua vor dem Essen','Bismillah','Im Namen Allahs','Dieses Dua wird vor dem Essen rezitiert, um Allahs Segen auf das Essen zu erbitten','Segen auf dem Essen, Schutz vor Schaden, Dankbarkeit'),
('dua-food-1','en','Dua Before Eating','Bismillah','In the name of Allah','','This dua is recited before eating to seek Allah\'s blessings and remember that He is the provider of all sustenance.'),
('dua-food-1','es','Dua antes de comer','Bismillah','En el nombre de Alá','Este dua se recita antes de comer para buscar las bendiciones de Alá en la comida','Bendiciones en la comida, protección contra el daño, gratitud'),
('dua-food-1','id','Doa sebelum makan','Bismillah','Dengan nama Allah','Doa ini dibaca sebelum makan untuk memohon berkah Allah pada makanan','Berkah pada makanan, perlindungan dari bahaya, syukur'),
('dua-food-1','ur','کھانے سے پہلے کی دعا','بسم اللہ','اللہ کے نام سے','یہ دعا کھانے سے پہلے کھانے پر اللہ کی برکت کے لیے پڑھی جاتی ہے','کھانے پر برکت، نقصان سے حفاظت، شکرگزاری'),
('dua-gratitude-1','en','Dua for Gratitude','Allahumma lakal-hamdu hatta tardha, wa lakal-hamdu idha radita, wa lakal-hamdu ba\'dar-rida','O Allah, to You belongs all praise until You are pleased, and to You belongs all praise when You are pleased, and to You belongs all praise after You are pleased','','This dua expresses complete gratitude to Allah in all circumstances.'),
('dua-hajj-umrah-1','en','Dua for Hajj and Umrah','Allahumma inni uridul-hajja fa-yassirhu li wa taqabbalhu minni','O Allah, I intend to perform Hajj, so make it easy for me and accept it from me','','This dua is recited when intending to perform Hajj or Umrah to seek Allah\'s facilitation and acceptance.'),
('dua-illness-1','ar','دعاء الشفاء','أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ','أسأل الله العظيم رب العرش العظيم أن يشفيك','يُقرأ هذا الدعاء للشفاء والتعافي من المرض','الشفاء من المرض، القوة الروحية، رحمة الله'),
('dua-illness-1','bn','সুস্থতার দুআ','আসআলু আল্লাহাল আজীম, রাব্বাল আরশিল আজীম আন ইয়াশফিয়াক','আমি আল্লাহ মহান, মহান আরশের প্রভুকে আপনাকে সুস্থ করার জন্য জিজ্ঞাসা করছি','এই দুআটি অসুস্থতা থেকে সুস্থতা এবং পুনরুদ্ধারের জন্য পাঠ করা হয়','অসুস্থতা থেকে সুস্থতা, আধ্যাত্মিক শক্তি, ঐশ্বরিক করুণা'),
('dua-illness-1','de','Dua für Heilung','As\'alu Allaha al-\'Adheem, Rabbal-\'Arshil-\'Adheem an yashfiyak','Ich bitte Allah den Allmächtigen, Herrn des Großen Thrones, dich zu heilen','Dieses Dua wird für Heilung und Genesung von Krankheit rezitiert','Heilung von Krankheit, spirituelle Stärke, göttliche Barmherzigkeit'),
('dua-illness-1','en','Dua for Illness','As\'alullaha al-\'adheem rabbal-\'arshil-\'adheem an yashfiyak','I ask Allah the Most Great, Lord of the Great Throne, to heal you','','This dua is recited for healing and seeking Allah\'s cure for illnesses.'),
('dua-illness-1','es','Dua para la curación','As\'alu Allaha al-\'Adheem, Rabbal-\'Arshil-\'Adheem an yashfiyak','Le pido a Alá el Más Grande, Señor del Gran Trono, que te cure','Este dua se recita para la curación y recuperación de la enfermedad','Curación de la enfermedad, fuerza espiritual, misericordia divina'),
('dua-illness-1','id','Doa untuk kesembuhan','As\'alu Allaha al-\'Adheem, Rabbal-\'Arshil-\'Adheem an yashfiyak','Saya memohon kepada Allah Yang Maha Agung, Tuhan Arsy Yang Agung, untuk menyembuhkanmu','Doa ini dibaca untuk kesembuhan dan pemulihan dari penyakit','Kesembuhan dari penyakit, kekuatan spiritual, rahmat ilahi'),
('dua-illness-1','ur','شفا کی دعا','اسال اللہ العظیم رب العرش العظیم ان یشفیاک','میں اللہ عظیم، عرش عظیم کے رب سے آپ کو شفا دینے کی درخواست کرتا ہوں','یہ دعا بیماری سے شفا اور صحت یابی کے لیے پڑھی جاتی ہے','بیماری سے شفا، روحانی طاقت، الہی رحمت'),
('dua-morning-1','ar','دعاء الصباح','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','يُقرأ هذا الدعاء في الصباح لطلب حماية الله وبركاته لليوم','الحماية لليوم، البركات، القوة الروحية'),
('dua-morning-1','bn','সকালের দুআ','আসবাহনা ওয়া আসবাহাল মুলকু লিল্লাহ, ওয়ালহামদু লিল্লাহ, লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহ','আমরা সকালে পৌঁছেছি এবং এই মুহূর্তে সব সার্বভৌমত্ব আল্লাহর। সব প্রশংসা আল্লাহর জন্য। আল্লাহ ছাড়া কেউ উপাসনার যোগ্য নয়, তিনি একক, কোনো অংশীদার ছাড়া','এই দুআটি সকালে আল্লাহর সুরক্ষা এবং দিনের জন্য বরকত কামনা করার জন্য পাঠ করা হয়','দিনের জন্য সুরক্ষা, বরকত, আধ্যাত্মিক শক্তি'),
('dua-morning-1','de','Morgen-Dua','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Wir haben den Morgen erreicht und zu dieser Zeit gehört alle Souveränität Allah. Aller Preis gebührt Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne Partner','Dieses Dua wird morgens rezitiert, um Allahs Schutz und Segen für den Tag zu erbitten','Schutz für den Tag, Segen, spirituelle Stärke'),
('dua-morning-1','en','Dua for Morning','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','We have reached the morning and at this very time all sovereignty belongs to Allah. All praise is for Allah. None has the right to be worshipped except Allah, alone, without any partner.','','This dua is recited in the morning to seek Allah\'s protection and blessings for the day ahead.'),
('dua-morning-1','es','Dua de la mañana','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Hemos llegado a la mañana y en este momento toda soberanía pertenece a Alá. Toda alabanza es para Alá. Nadie tiene derecho a ser adorado excepto Alá, solo, sin ningún socio','Este dua se recita por la mañana para buscar la protección y bendiciones de Alá para el día','Protección para el día, bendiciones, fuerza espiritual'),
('dua-morning-1','id','Doa pagi','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Kami telah mencapai pagi dan pada saat ini semua kedaulatan milik Allah. Semua pujian untuk Allah. Tidak ada yang berhak disembah kecuali Allah, sendirian, tanpa partner','Doa ini dibaca di pagi hari untuk memohon perlindungan dan berkah Allah untuk hari ini','Perlindungan untuk hari ini, berkah, kekuatan spiritual'),
('dua-morning-1','ur','صبح کی دعا','اصبحنا واصبح الملک للہ، والحمد للہ، لا الہ الا اللہ وحدہ لا شریک لہ','ہم صبح کو پہنچ گئے اور اس وقت تمام بادشاہی اللہ کی ہے۔ تمام تعریفیں اللہ کے لیے ہیں۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، کوئی شریک نہیں','یہ دعا صبح کو اللہ کی حفاظت اور دن کی برکت کے لیے پڑھی جاتی ہے','دن کی حفاظت، برکتیں، روحانی طاقت'),
('dua-nature-1','en','Dua for Rain','Allahumma sayyiban nafi\'an','O Allah, (bring) beneficial rain clouds','','This dua is recited when it rains to seek Allah\'s blessings and beneficial rain.'),
('dua-purification-1','en','Dua for Purification','Allahumma tahhirni minadh-dhunubi wal-khataaya kama yutahharuth-thawbul-abyadu minad-danas','O Allah, purify me from sins and mistakes as a white garment is purified from filth','','This dua is recited to seek Allah\'s purification from sins and spiritual cleansing.'),
('dua-ramadan-1','en','Dua for Ramadan','Allahumma inni as\'alukal jannata wa a\'udhu bika minan naar','O Allah, I ask You for Paradise and I seek refuge with You from the Fire','','This dua is recited during Ramadan to seek Allah\'s mercy and ask for Paradise while seeking refuge from Hell.'),
('dua-rizq-1','ar','دعاء الرزق','اللَّهُمَّ إِنِّي أَسْأَلُكَ رِزْقاً طَيِّباً وَرَزْقاً وَاسِعاً','يا الله، أسألك رزقاً طيباً ورزقاً واسعاً','يُقرأ هذا الدعاء لطلب رزق جيد ووفير من الله','الرزق الوفير، البركات المالية، الرزق الإلهي'),
('dua-rizq-1','bn','রিজিকের দুআ','আল্লাহুম্মা ইন্নি আসআলুকা রিজকান তাইয়্যিবান ওয়া রিজকান ওয়াসিয়ান','হে আল্লাহ, আমি আপনাকে উত্তম এবং প্রচুর রিজিক চাইছি','এই দুআটি আল্লাহর কাছ থেকে উত্তম এবং প্রচুর রিজিক কামনা করার জন্য পাঠ করা হয়','প্রচুর রিজিক, আর্থিক বরকত, ঐশ্বরিক সরবরাহ'),
('dua-rizq-1','de','Dua für Versorgung','Allahumma inni as\'aluka rizqan tayyiban wa rizqan wasi\'an','O Allah, ich bitte Dich um guten und reichlichen Unterhalt','Dieses Dua wird rezitiert, um guten und reichlichen Unterhalt von Allah zu erbitten','Reichlicher Unterhalt, finanzielle Segnungen, göttliche Versorgung'),
('dua-rizq-1','en','Dua for Rizq (Provision)','Allahumma inni as\'aluka rizqan tayyiban wa rizqan wasi\'an','O Allah, I ask You for good and abundant provision','','This dua is recited to seek Allah\'s blessings for lawful and abundant provision.'),
('dua-rizq-1','es','Dua para el sustento','Allahumma inni as\'aluka rizqan tayyiban wa rizqan wasi\'an','Oh Alá, te pido sustento bueno y abundante','Este dua se recita para pedir sustento bueno y abundante de Alá','Sustento abundante, bendiciones financieras, provisión divina'),
('dua-rizq-1','id','Doa untuk rezeki','Allahumma inni as\'aluka rizqan tayyiban wa rizqan wasi\'an','Ya Allah, aku memohon kepada-Mu rezeki yang baik dan melimpah','Doa ini dibaca untuk memohon rezeki yang baik dan melimpah dari Allah','Rezeki melimpah, berkah finansial, penyediaan ilahi'),
('dua-rizq-1','ur','رزق کی دعا','اللہم انی اسالک رزقا طیبا ورزقا واسعا','اے اللہ! میں آپ سے اچھا اور وسیع رزق مانگتا ہوں','یہ دعا اللہ سے اچھا اور وسیع رزق مانگنے کے لیے پڑھی جاتی ہے','وسیع رزق، مالی برکتیں، الہی فراہمی'),
('dua-ruqyah-1','en','Dua for Protection (Ruqyah)','A\'udhu bi-kalimatillahit-tammatil-lati la yujawizuhunna barrun wa la fajir','I seek refuge in the perfect words of Allah which neither the upright nor the corrupt can overcome','','This dua provides protection from evil and harm through Allah\'s perfect words.'),
('dua-salah-1','en','Dua Before Salah','Allahumma ba\'id bayni wa bayna khataayaya kama ba\'adta baynal-mashriqi wal-maghrib','O Allah, distance me from my sins as You have distanced the East from the West','','This dua is recited before salah to seek Allah\'s forgiveness and purification from sins.'),
('dua-sleep-1','en','Dua Before Sleeping','Bismika rabbi wada\'tu janbi, wa bika arfa\'uhu, fa-in amsakta nafsi farhamha, wa-in arsaltaha fahfazha bima tahfazu bihi \'ibadakas-saliheen','In Your name, my Lord, I lay my side down, and in Your name I raise it. If You should take my soul then have mercy upon it, and if You should return my soul then protect it in the manner You do so with Your righteous servants','','This dua is recited before sleeping to seek Allah\'s protection and mercy during sleep.'),
('dua-travel-1','en','Dua for Travel','Allahumma inna nas\'aluka fi safarina haadha al-birra wat-taqwa','O Allah, we ask You on this journey of ours for righteousness and piety','','This dua is recited when starting a journey to seek Allah\'s protection and guidance for safe travel.'),
('h1','ar','دعاء الصباح','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','يُقرأ هذا الدعاء في الصباح لطلب حماية الله وبركاته لليوم','الحماية لليوم، البركات، القوة الروحية'),
('h1','bn','সকালের দোয়া','আসবাহনা ওয়া আসবাহাল-মুলকু লিল্লাহ, ওয়ালহামদু লিল্লাহ, লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহ','আমরা সকালে পৌঁছেছি এবং এই মুহূর্তে সমস্ত সার্বভৌমত্ব আল্লাহর জন্য। সকল প্রশংসা আল্লাহর জন্য। আল্লাহ ছাড়া কোন ইলাহ নেই, তিনি একক, কোন অংশীদার নেই।','','এই দোয়া সারা দিনের জন্য বরকত ও সুরক্ষা আনে। ফজর নামাজের পর প্রতিদিন সকালে এটি পাঠ করার পরামর্শ দেওয়া হয়।'),
('h1','de','Morgen-Dua','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Wir haben den Morgen erreicht und zu dieser Zeit gehört alle Souveränität Allah. Aller Preis gebührt Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne Partner','Dieses Dua wird morgens rezitiert, um Allahs Schutz und Segen für den Tag zu erbitten','Schutz für den Tag, Segen, spirituelle Stärke'),
('h1','en','Dua for Morning','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','We have reached the morning and at this very time all sovereignty belongs to Allah. All praise is for Allah. None has the right to be worshipped except Allah, alone, without any partner.','','This dua is recited in the morning to seek Allah\'s protection and blessings for the day ahead.'),
('h1','es','Dua de la mañana','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Hemos llegado a la mañana y en este momento toda soberanía pertenece a Alá. Toda alabanza es para Alá. Nadie tiene derecho a ser adorado excepto Alá, solo, sin ningún socio','Este dua se recita por la mañana para buscar la protección y bendiciones de Alá para el día','Protección para el día, bendiciones, fuerza espiritual'),
('h1','id','Doa pagi','Asbahna wa asbahal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Kami telah mencapai pagi dan pada saat ini semua kedaulatan milik Allah. Semua pujian untuk Allah. Tidak ada yang berhak disembah kecuali Allah, sendirian, tanpa partner','Doa ini dibaca di pagi hari untuk memohon perlindungan dan berkah Allah untuk hari ini','Perlindungan untuk hari ini, berkah, kekuatan spiritual'),
('h1','ur','صبح کی دعا','اصبحنا واصبح الملک للہ، والحمد للہ، لا الہ الا اللہ وحدہ لا شریک لہ','ہم صبح کو پہنچ گئے اور اس وقت تمام بادشاہی اللہ کی ہے۔ تمام تعریفیں اللہ کے لیے ہیں۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، کوئی شریک نہیں','یہ دعا صبح کو اللہ کی حفاظت اور دن کی برکت کے لیے پڑھی جاتی ہے','دن کی حفاظت، برکتیں، روحانی طاقت'),
('h2','ar','دعاء المساء','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ','يُقرأ هذا الدعاء في المساء لطلب حماية الله وبركاته للليل','الحماية للليل، البركات، القوة الروحية'),
('h2','bn','সন্ধ্যার দোয়া','আমসাইনা ওয়া আমসাল-মুলকু লিল্লাহ, ওয়ালহামদু লিল্লাহ, লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহ','আমরা সন্ধ্যার পৌঁছেছি এবং এই মুহূর্তে সমস্ত সার্বভৌমত্ব আল্লাহর জন্য। সকল প্রশংসা আল্লাহর জন্য। আল্লাহ ছাড়া কোন ইলাহ নেই, তিনি একক, কোন অংশীদার নেই।','','এই দোয়া সন্ধ্যার প্রতিদিন আল্লাহর জন্য বরকত ও তাঁর রাতের জন্য সুরক্ষা প্রার্থনা করার পরামর্শ দেওয়া হয়।'),
('h2','de','Abend-Dua','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Wir haben den Abend erreicht und zu dieser Zeit gehört alle Souveränität Allah. Aller Preis gebührt Allah. Niemand hat das Recht, angebetet zu werden, außer Allah, allein, ohne Partner','Dieses Dua wird abends rezitiert, um Allahs Schutz und Segen für die Nacht zu erbitten','Schutz für die Nacht, Segen, spirituelle Stärke'),
('h2','en','Dua for Evening','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','We have reached the evening and at this very time all sovereignty belongs to Allah. All praise is for Allah. None has the right to be worshipped except Allah, alone, without any partner.','','This dua is recited in the evening to thank Allah for the day and seek His protection for the night.'),
('h2','es','Dua de la tarde','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Hemos llegado a la tarde y en este momento toda soberanía pertenece a Alá. Toda alabanza es para Alá. Nadie tiene derecho a ser adorado excepto Alá, solo, sin ningún socio','Este dua se recita por la tarde para buscar la protección y bendiciones de Alá para la noche','Protección para la noche, bendiciones, fuerza espiritual'),
('h2','id','Doa sore','Amsayna wa amsal mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la shareeka lah','Kami telah mencapai sore dan pada saat ini semua kedaulatan milik Allah. Semua pujian untuk Allah. Tidak ada yang berhak disembah kecuali Allah, sendirian, tanpa partner','Doa ini dibaca di sore hari untuk memohon perlindungan dan berkah Allah untuk malam ini','Perlindungan untuk malam ini, berkah, kekuatan spiritual'),
('h2','ur','شام کی دعا','امسینا وامسا الملک للہ، والحمد للہ، لا الہ الا اللہ وحدہ لا شریک لہ','ہم شام کو پہنچ گئے اور اس وقت تمام بادشاہی اللہ کی ہے۔ تمام تعریفیں اللہ کے لیے ہیں۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، کوئی شریک نہیں','یہ دعا شام کو اللہ کی حفاظت اور رات کی برکت کے لیے پڑھی جاتی ہے','رات کی حفاظت، برکتیں، روحانی طاقت'),
('h3','ar','الدعاء قبل الأكل','بِسْمِ اللَّهِ','باسم الله','يُقرأ هذا الدعاء قبل الأكل لطلب بركة الله على الطعام','البركة على الطعام، الحماية من الأذى، الشكر'),
('h3','bn','খাওয়ার আগের দুআ','বিসমিল্লাহ','আল্লাহর নামে','এই দুআটি খাওয়ার আগে খাবারে আল্লাহর বরকত কামনা করার জন্য পাঠ করা হয়','খাবারে বরকত, ক্ষতি থেকে সুরক্ষা, কৃতজ্ঞতা'),
('h3','de','Dua vor dem Essen','Bismillah','Im Namen Allahs','Dieses Dua wird vor dem Essen rezitiert, um Allahs Segen auf das Essen zu erbitten','Segen auf dem Essen, Schutz vor Schaden, Dankbarkeit'),
('h3','en','Dua before Eating','Bismillah','In the name of Allah','','This dua is recited before eating to seek Allah\'s blessings and remember that He is the provider of all sustenance.'),
('h3','es','Dua antes de comer','Bismillah','En el nombre de Alá','Este dua se recita antes de comer para buscar las bendiciones de Alá en la comida','Bendiciones en la comida, protección contra el daño, gratitud'),
('h3','id','Doa sebelum makan','Bismillah','Dengan nama Allah','Doa ini dibaca sebelum makan untuk memohon berkah Allah pada makanan','Berkah pada makanan, perlindungan dari bahaya, syukur'),
('h3','ur','کھانے سے پہلے کی دعا','بسم اللہ','اللہ کے نام سے','یہ دعا کھانے سے پہلے کھانے پر اللہ کی برکت کے لیے پڑھی جاتی ہے','کھانے پر برکت، نقصان سے حفاظت، شکرگزاری'),
('h4','en','Dua after Eating','Alhamdu lillahil-ladhi at\'amani haadha wa razaqanihi min ghayri hawlin minni wa la quwwah','All praise is for Allah who fed me this and provided it for me, with no power or might from myself','','This dua is recited after eating to thank Allah for the food and acknowledge that all provision comes from Him.'),
('h5','en','Dua for Travel','Allahumma inna nas\'aluka fi safarina haadha al-birra wat-taqwa','O Allah, we ask You on this journey of ours for righteousness and piety','','This dua is recited when starting a journey to seek Allah\'s protection and guidance for safe travel.'),
('h6','en','Dua for Entering Home','Bismillahi wa lajna, wa bismillahi kharajna, wa \'alallahi rabbina tawakkalna','In the name of Allah we enter, in the name of Allah we leave, and upon our Lord we place our trust','','This dua is recited when entering home to seek Allah\'s protection and blessings for the household.'),
('h7','en','Dua for Leaving Home','Bismillah, tawakkaltu \'alallahi, wa la hawla wa la quwwata illa billah','In the name of Allah, I place my trust in Allah, and there is no power and no strength except with Allah','','This dua is recited when leaving home to seek Allah\'s protection and guidance throughout the day.'),
('h8','en','Dua for Wearing Clothes','Alhamdu lillahil-ladhi kasani haadha wa razaqanihi min ghayri hawlin minni wa la quwwah','All praise is for Allah who has clothed me with this and provided it for me, with no power or might from myself','','This dua is recited when wearing clothes to thank Allah for the clothing and acknowledge His blessings.'),
('q1','ar','آية الكرسي','Allahu la ilaha illa huwal-hayyul-qayyum. La ta\'khudhuhu sinatuw-wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa\'u \'indahu illa bi-idhnih. Ya\'lamu ma bayna aydeehim wa ma khalfahum. Wa la yuhituna bi-shay\'im-min \'ilmihi illa bima sha\'a. Wasi\'a kursiyyuhus-samawati wal-ard. Wa la ya\'uduhu hifdhuhuma. Wa huwal-\'aliyyul-\'adheem.','الله لا إله إلا هو الحي القيوم لا تأخذه سنة ولا نوم له ما في السماوات وما في الأرض من ذا الذي يشفع عنده إلا بإذنه يعلم ما بين أيديهم وما خلفهم ولا يحيطون بشيء من علمه إلا بما شاء وسع كرسيه السماوات والأرض ولا يؤوده حفظهما وهو العلي العظيم','','آية الكرسي هي أعظم آية في القرآن. توفر الحماية من الشر، تجلب البركات، ويوصى بقراءتها للحماية طوال النهار والليل.'),
('q1','bn','আয়াতুল কুরসী','আল্লাহু লা ইলাহা ইল্লা হুয়াল-হাইয়্যুল-কাইয়্যুম। লা তা\'খুযুহু সিনাতুও-ওয়া লা নাউম। লাহু মা ফিস-সামাওয়াতি ওয়া মা ফিল-আর্দ। মান যাল-লাযি ইয়াশফা\'উ \'ইন্দাহু ইল্লা বি-ইযনিহ। ইয়া\'লামু মা বায়না আইদিহিম ওয়া মা খালফাহুম। ওয়া লা ইউহিতুনা বি-শাই\'ইম-মিন \'ইলমিহি ইল্লা বিমা শা\'আ। ওয়াসি\'আ কুরসিয়্যুহুস-সামাওয়াতি ওয়াল-আর্দ। ওয়া লা ইয়া\'উদুহু হিফযুহুমা। ওয়া হুয়াল-\'আলিয়্যুল-\'আযম।','আল্লাহ - তিনি ছাড়া কোন ইলাহ নেই, তিনি চিরঞ্জীব, স্বয়ংসম্পূর্ণ। তাঁকে তন্দ্রা বা নিদ্রা স্পর্শ করে না। আকাশমণ্ডলী ও পৃথিবীতে যা কিছু আছে সবই তাঁর। কে এমন আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করতে পারে? তিনি জানেন তাদের সামনে যা আছে এবং তাদের পিছনে যা আছে। তারা তাঁর জ্ঞানের কোন বিষয়েই পরিবেষ্টন করতে পারে না, তিনি যা ইচ্ছা করেন তা ছাড়া। তাঁর কুরসী আকাশমণ্ডলী ও পৃথিবী পরিবেষ্টন করে আছে। আর এ দুটির সংরক্ষণ তাঁকে ক্লান্ত করে না। তিনি সর্বোচ্চ, সর্বশ্রেষ্ঠ।','','আয়াতুল কুরসী কুরআনের সর্বশ্রেষ্ঠ আয়াত। এটি মন্দ থেকে সুরক্ষা দেয়, বরকত আনে এবং দিনরাত সুরক্ষার জন্য পাঠ করার পরামর্শ দেওয়া হয়।'),
('q1','en','Ayat Al-Kursi','Allahu la ilaha illa huwal-hayyul-qayyum. La ta\'khudhuhu sinatuw-wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa\'u \'indahu illa bi-idhnih. Ya\'lamu ma bayna aydeehim wa ma khalfahum. Wa la yuhituna bi-shay\'im-min \'ilmihi illa bima sha\'a. Wasi\'a kursiyyuhus-samawati wal-ard. Wa la ya\'uduhu hifdhuhuma. Wa huwal-\'aliyyul-\'adheem.','Allah - there is no deity except Him, the Ever-Living, the Self-Sustaining. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.','','Ayat Al-Kursi is the greatest verse in the Quran. It provides protection from evil, brings blessings, and is recommended to be recited for protection throughout the day and night.'),
('q2','bn','সূরা আল-ফাতিহা','বিসমিল্লাহি আর-রাহমানি আর-রাহীম। আলহামদু লিল্লাহি রাব্বিল-\'আলামীন। আর-রাহমানি আর-রাহীম। মালিকি ইয়াওমিদ-দীন। ইয়্যাকা না\'বুদু ওয়া ইয়্যাকা নাসতাঈন। ইহদিনাস-সিরাতাল-মুসতাকীম। সিরাতাল-লাযীনা আন\'আমতা \'আলাইহিম গাইরিল-মাগদূবি \'আলাইহিম ওয়া লাদ-দাল্লীন।','পরম করুণাময় অসীম দয়াময় আল্লাহর নামে। সকল প্রশংসা আল্লাহর জন্য, যিনি সকল সৃষ্টি জগতের পালনকর্তা। পরম করুণাময় অসীম দয়াময়। বিচারের দিনের মালিক। আমরা একমাত্র তোমারই ইবাদত করি এবং একমাত্র তোমারই নিকট সাহায্য প্রার্থনা করি। আমাদেরকে সরল পথ দেখাও। তাদের পথ, যাদেরকে তুমি নেয়ামত দান করেছ। তাদের পথ নয়, যাদের প্রতি তোমার গজব নাযিল হয়েছে এবং যারা পথভ্রষ্ট হয়েছে।','','সূরা আল-ফাতিহা কুরআনের প্রথম অধ্যায় এবং প্রতিটি নামাজের জন্য অত্যাবশ্যক। এতে কুরআনের সারমর্ম রয়েছে এবং এটি দিকনির্দেশনা ও বরকতের জন্য একটি শক্তিশালী দোয়া।'),
('q2','en','Surah Al-Fatiha','Bismillahi ar-Rahmani ar-Raheem. Alhamdu lillahi rabbil-\'alameen. Ar-Rahmani ar-Raheem. Maliki yawmid-deen. Iyyaka na\'budu wa iyyaka nasta\'een. Ihdinas-siratal-mustaqeem. Siratal-ladheena an\'amta \'alayhim ghayril-maghdoobi \'alayhim wa lad-dalleen.','In the name of Allah, the Most Gracious, the Most Merciful. All praise is due to Allah, Lord of the worlds. The Most Gracious, the Most Merciful. Master of the Day of Judgment. It is You we worship and You we ask for help. Guide us to the straight path. The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.','','Surah Al-Fatiha is the opening chapter of the Quran and is essential for every prayer. It contains the essence of the Quran and is a powerful dua for guidance and blessings.'),
('q3','en','Surah Al-Ikhlas','Bismillahi ar-Rahmani ar-Raheem. Qul huwa Allahu ahad. Allahus-samad. Lam yalid wa lam yoolad. Wa lam yakun lahu kufuwan ahad.','In the name of Allah, the Most Gracious, the Most Merciful. Say, \"He is Allah, [who is] One. Allah, the Eternal Refuge. He neither begets nor is born. Nor is there to Him any equivalent.\"','','Surah Al-Ikhlas is equivalent to one-third of the Quran. It emphasizes the pure monotheism of Allah and provides protection and blessings when recited regularly.'),
('q4','en','Surah Al-Falaq','Bismillahi ar-Rahmani ar-Raheem. Qul a\'udhu bi-rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-\'uqad. Wa min sharri hasidin idha hasad.','In the name of Allah, the Most Gracious, the Most Merciful. Say, \"I seek refuge in the Lord of daybreak. From the evil of that which He created. And from the evil of darkness when it settles. And from the evil of the blowers in knots. And from the evil of an envier when he envies.\"','','Surah Al-Falaq is one of the Mu\'awwidhatayn (the two surahs of refuge). It provides protection from evil, black magic, and the evil eye.'),
('q5','en','Surah An-Nas','Bismillahi ar-Rahmani ar-Raheem. Qul a\'udhu bi-rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fee sudoorin-nas. Minal-jinnati wan-nas.','In the name of Allah, the Most Gracious, the Most Merciful. Say, \"I seek refuge in the Lord of mankind. The Sovereign of mankind. The God of mankind. From the evil of the retreating whisperer. Who whispers [evil] into the breasts of mankind. From among the jinn and mankind.\"','','Surah An-Nas is the second of the Mu\'awwidhatayn. It provides protection from evil whispers, jinn, and negative influences.'),
('q6','en','Surah Al-Mulk','Bismillahi ar-Rahmani ar-Raheem. Tabarakal-ladhi bi-yadihil-mulk wa huwa \'ala kulli shay\'in qadeer. Alladhi khalaqal-mawta wal-hayata li-yabluwakum ayyukum ahsanu \'amala. Wa huwal-\'azeezul-ghafoor.','In the name of Allah, the Most Gracious, the Most Merciful. Blessed is He in whose hand is dominion, and He is over all things competent. [And] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving.','','Surah Al-Mulk is known as the protector from the punishment of the grave. It is recommended to recite it before sleeping.'),
('q7','en','Surah Ya-Sin','Bismillahi ar-Rahmani ar-Raheem. Ya-Sin. Wal-Qur\'anil-hakeem. Innaka laminal-mursaleen. \'Ala siratim-mustaqeem.','In the name of Allah, the Most Gracious, the Most Merciful. Ya, Seen. By the wise Quran. Indeed, [O Muhammad], you are from among the messengers. On a straight path.','','Surah Ya-Sin is the heart of the Quran. It provides numerous benefits including ease in death, protection, and increased blessings.'),
('q8','en','Surah Al-Waqiah','Bismillahi ar-Rahmani ar-Raheem. Iza waqa\'atil-waqi\'ah. Laisa li-waq\'atiha kazibah. Khafidatur-rafi\'ah. Iza rujjatil-ardu rajja.','In the name of Allah, the Most Gracious, the Most Merciful. When the Event occurs, there is no denying that it will occur. It will bring low [some] and bring high [others]. When the earth is shaken with convulsion.','','Surah Al-Waqiah is known as the surah of wealth and sustenance. Reciting it regularly helps increase rizq (provision) and protects from poverty.');
